userDefinedLinkHintCss:
/* Hacker Theme */

/* Link hint boxes */
div > .vimiumHintMarker {
  background: #000000;
  font-size: 12px;
  border: 0.15em solid rgba(233, 135, 58, 0.35);
  border-radius: 1.0em;
  box-shadow: 0em 0.1em 0.6em 0.1em rgba(233, 135, 58, 0.2);
}

/* Link hint text */
div > .vimiumHintMarker span {
  color: #E9873A;
  font-size: inherit;
  text-shadow: none;
}

/* Link hint matching characters */
div > .vimiumHintMarker > .matchingCharacter {
  color: #E9873A;
}

input#vomnibarInput.vimiumReset {
	color: #E9873A !important;
  background-color: #111 !important;
}

#vomnibar {
   border-color: rgba(233, 135, 58, 0.35);
   background-color: #222;
   box-shadow: 0em 0.1em 0.6em 0.1em rgba(233, 135, 58, 0.35);
}

#vomnibar .vomnibarSearchArea {
   background-color: #222;
   border-bottom: rgba(233, 135, 58, 0.35);
}

#vomnibar li .vomnibarTopHalf .vomnibarSource {
	color: #E9873A;
}

#vomnibar input {
   border-color: #393939;
   background-color: #222;
   color: #E9873A;
}

#vomnibar ul {
    background-color: #222;
}

#vomnibar li {
   border-bottom: #3f3f3f;
}

#vomnibar li .vomnibarUrl {
   color: #E9873A;
}

#vomnibar li .vomnibarMatch {
   color: white;
}

#vomnibar li.vomnibarSelected {
    background-color: rgba(233, 135, 58, 0.5);
}

#vomnibar li em .vomnibarMatch, #vomnibar li .vomnibarTitle .vomnibarMatch {
   color: white;
}

#vomnibar li em, #vomnibar li .vomnibarTitle {
   color: #ddd;
}

/* Link hint matching characters */
div > .vimiumHintMarker > .matchingCharacter {
  color: #FFFFFF;
}
